// Parse one Telegram message into an action: add | report | undo | help
const cfg = $('Prepare Configuration Settings').first().json;
const msg = $('When Telegram Message Received').first().json.message || {};
const chatId = String(msg.chat?.id ?? '');
const text = String(msg.text || '').trim();
const tz = cfg.timezone || 'UTC';
const when = msg.date ? DateTime.fromSeconds(msg.date, { zone: tz }) : DateTime.now().setZone(tz);

const base = { chat_id: chatId, month: when.toFormat('yyyy-MM'), spent_at: when.toISO() };

if (!text || text === '/start' || text === '/help') return [{ json: { ...base, action: 'help' } }];
if (text.startsWith('/undo')) return [{ json: { ...base, action: 'undo' } }];
if (text.startsWith('/report')) {
  const m = text.match(/(\d{4})-(\d{1,2})/);
  const month = m ? `${m[1]}-${m[2].padStart(2, '0')}` : base.month;
  return [{ json: { ...base, action: 'report', month } }];
}

// ---- amount: first number in the message, understands 50k / 1.5tr / 2m / 120.000 / 12.50 / $12 ----
const re = /(\d+(?:[.,]\d+)*)\s*(k|nghìn|ngàn|tr|triệu|trieu|m|mil|million)?(?![a-zà-ỹ])/i;
const hit = text.toLowerCase().match(re);
if (!hit) return [{ json: { ...base, action: 'help', error: 'no_amount' } }];

let raw = hit[1];
const unit = (hit[2] || '').toLowerCase();
let n;
if (/^\d{1,3}([.,]\d{3})+$/.test(raw) && !unit) n = Number(raw.replace(/[.,]/g, ''));   // 120.000 / 1,250,000
else n = Number(raw.replace(',', '.'));                                                  // 12.5 / 1,5
if (['k', 'nghìn', 'ngàn'].includes(unit)) n *= 1e3;
if (['tr', 'triệu', 'trieu', 'm', 'mil', 'million'].includes(unit)) n *= 1e6;
// Many VND users type "50" meaning 50,000
if (!unit && cfg.smallNumbersAreThousands && n > 0 && n < 1000) n *= 1e3;
if (!(n > 0)) return [{ json: { ...base, action: 'help', error: 'no_amount' } }];

// ---- category: "#tag" overrides, else keyword rules from Config ----
let note = text.replace(hit[0], ' ').replace(/#\S+/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (text.match(/#(\S+)/) || [])[1];
const rules = cfg.categoryKeywords || {};
let category = 'Other';
if (tag) {
  const t = tag.toLowerCase();
  category = Object.keys(rules).find(c => c.toLowerCase().startsWith(t)) || (tag[0].toUpperCase() + tag.slice(1));
} else {
  const low = ' ' + note.toLowerCase() + ' ';
  for (const [cat, words] of Object.entries(rules)) {
    if (words.some(w => low.includes(w.toLowerCase()))) { category = cat; break; }
  }
}
return [{ json: { ...base, action: 'add', amount: Math.round(n * 100) / 100, category, note: note || category } }];

// Keep exactly the Data Table columns (auto-map inserts every field it receives)
const j = $json;
return { json: { chat_id: j.chat_id, amount: j.amount, category: j.category, note: j.note, month: j.month, spent_at: j.spent_at } };

const cfg = $('Prepare Configuration Settings').first().json;
const fmt = v => new Intl.NumberFormat(cfg.locale, { style: 'currency', currency: cfg.currency, maximumFractionDigits: cfg.currency === 'VND' ? 0 : 2 }).format(v);
const r = $json;
return { json: { chat_id: r.chat_id, text: `✅ Saved ${fmt(r.amount)} · ${r.category}\n📝 ${r.note}\n\nType /report for this month, /undo to remove it.` } };

// Monthly report from all rows of this chat + month (runs once for all items)
const cfg = $('Prepare Configuration Settings').first().json;
const req = $('Parse Telegram Message').first().json;
const fmt = v => new Intl.NumberFormat(cfg.locale, { style: 'currency', currency: cfg.currency, maximumFractionDigits: cfg.currency === 'VND' ? 0 : 2 }).format(v);
const rows = $input.all().map(i => i.json).filter(r => r && r.amount !== undefined && r.amount !== null);
if (!rows.length) return [{ json: { chat_id: req.chat_id, text: `📭 No expenses recorded for ${req.month} yet.\nSend something like "50k coffee" to start.` } }];

const total = rows.reduce((s, r) => s + Number(r.amount), 0);
const byCat = {};
for (const r of rows) byCat[r.category] = (byCat[r.category] || 0) + Number(r.amount);
const cats = Object.entries(byCat).sort((a, b) => b[1] - a[1]);
const bar = p => '▓'.repeat(Math.max(1, Math.round(p / 10))) + '░'.repeat(10 - Math.max(1, Math.round(p / 10)));
const lines = cats.map(([c, v]) => `${bar(v / total * 100)} ${c}: ${fmt(v)} (${Math.round(v / total * 100)}%)`);
const top = [...rows].sort((a, b) => b.amount - a.amount).slice(0, 3).map(r => `• ${fmt(r.amount)} — ${r.note}`);
const [y, m] = req.month.split('-').map(Number);
const now = DateTime.now().setZone(cfg.timezone || 'UTC');
const days = (now.year === y && now.month === m) ? now.day : DateTime.local(y, m).daysInMonth;
return [{ json: { chat_id: req.chat_id, text:
  `📊 Expenses ${req.month}\nTotal: ${fmt(total)} · ${rows.length} entries · ~${fmt(total / days)}/day\n\n` +
  lines.join('\n') + `\n\n🔝 Biggest:\n` + top.join('\n') } }];

const cfg = $('Prepare Configuration Settings').first().json;
const req = $('Parse Telegram Message').first().json;
const last = $('Locate Last Expense').all().map(i => i.json).find(r => r && r.id !== undefined);
const fmt = v => new Intl.NumberFormat(cfg.locale, { style: 'currency', currency: cfg.currency, maximumFractionDigits: cfg.currency === 'VND' ? 0 : 2 }).format(v);
return [{ json: { chat_id: req.chat_id, text: last ? `↩️ Removed ${fmt(last.amount)} · ${last.category} (${last.note})` : 'Nothing to undo.' } }];
